branch.sl.source:
// A branch, a colour literal and a function that returns a vector.
uniform float4 tint = #ff8040;

float2 swirl(float2 p, float a) {
    float c = cos(a);
    float s = sin(a);
    return float2(p.x * c - p.y * s, p.x * s + p.y * c);
}

float4 main() {
    float2 q = swirl(uv - 0.5, time * 0.3);
    float v = 0.25;
    if (q.x > 0.1) { v = 0.75; } else { v = fbm(q * 3, 4); }
    return float4(tint.rgb * v, 1);
}

cov-arith.sl.source:
// + - * / pow, unary -, rcp, min, max and clamp over continuous inputs. The
// stepwise ops are in step.sl: together they need more than the VM's eight
// registers.
float4 main() {
    float2 q = (uv - 0.5) * 6.0;
    float a = pow(abs(q.x) * 0.3, 1.7) + rcp(abs(q.y) + 1.0) - (-q.x) * 0.1;
    float c = q.y / (abs(q.x) + 2.0) + abs(q.y) * 0.1;
    return float4(saturate(a * 0.3), clamp(c * 0.5 + 0.5, 0.0, 1.0), min(max(a * 0.2, 0.1), 0.9), 1);
}

cov-exp.sl.source:
// atan2, exp, log and sqrt over continuous inputs, clear of atan2's seam.
float4 main() {
    float2 q = (uv - 0.5) * 2.0;
    float c = atan2(q.y + 0.013, q.x + 0.021) * 0.15 + exp(q.x) * 0.1;
    float d = log(q.y + 2.0) * 0.3 + sqrt(q.x + 1.0) * 0.2;
    return float4(saturate(c * 0.5 + 0.5), saturate(d), 0.5, 1);
}

cov-geom.sl.source:
// Vector geometry and the colour helpers, toLinear at three widths.
float4 main() {
    float2 q = uv - 0.5;
    float3 n = normalize(float3(q, 0.4));
    float3 r = reflect(float3(0.3, -0.5, -0.8), n);
    float3 c = cross(n, float3(0.0, 1.0, 0.0));
    float d = length(q) + distance(q, float2(0.2, 0.1)) * 0.5 + dot(q, float2(0.7, 0.3));
    float3 h = hsv2rgb(float3(frac(uv.x * 2.0), 0.8, 0.9));
    float l = luminance(h);
    float2 t2 = toLinear(uv);
    float t1 = toLinear(uv.y);
    float3 base = toLinear(float3(r.x * 0.5 + 0.5, c.z * 0.5 + 0.5, d * 0.7));
    return float4(base * l * 0.6 + h * 0.3 + float3(t2 * 0.2, t1 * 0.1), 1);
}

cov-interp.sl.source:
// lerp, step, smoothstep with its edges both ways round, and ?:.
float4 main() {
    float a = smoothstep(0.2, 0.8, uv.x);
    float b = smoothstep(0.7, 0.3, uv.y);
    float3 m = lerp(float3(0.1, 0.2, 0.9), float3(0.9, 0.6, 0.1), a);
    float s = step(0.5, uv.y);
    float3 c = uv.x > 0.3 ? m : float3(b, s, 0.5);
    return float4(c, 1);
}

cov-noise.sl.source:
// Every noise: value, simplex, fbm, turbulence, ridged, voronoi.
float4 main() {
    float2 p = uv * 5.0 + time * 0.1;
    float a = noise(p) * 0.5 + simplex(p * 1.3) * 0.5;
    float b = fbm(p, 3) * 0.5 + turbulence(p * 0.7, 2) * 0.5;
    float c = ridged(p * 0.6, 4) * 0.6 + voronoi(p * 1.5) * 0.4;
    return float4(a, b, c, 1);
}

cov-step.sl.source:
// floor, ceil, round, frac, sign and %. Every jump lands BETWEEN pixel centres
// at 96 px, so two backends a float ulp apart cannot land on opposite sides of
// one.
float4 main() {
    float2 q = (uv - 0.5) * 6.0;
    float b = (q.x % 0.5) + floor(q.y) * 0.1 + ceil(q.x) * 0.05 + round(q.y) * 0.03;
    float c = frac(uv.x * 4.0) + sign(q.x) * 0.2;
    return float4(clamp(b * 0.5 + 0.5, 0.0, 1.0), saturate(c * 0.5), 0.5, 1);
}

cov-trig.sl.source:
// Trigonometry over continuous inputs. exp, log, sqrt and atan2 are in
// exp.sl: together they need more than the VM's eight registers.
float4 main() {
    float2 q = (uv - 0.5) * 2.0;
    float a = sin(q.x * 5.0) * cos(q.y * 4.0) * 0.5 + 0.5;
    float b = tan(q.x * 0.6) * 0.3 + asin(q.y * 0.9) * 0.2 + acos(q.x * 0.9) * 0.1;
    return float4(a, saturate(b + 0.5), 0.5, 1);
}

cov-uniforms.sl.source:
// Uniforms at every width and a texture, so the host's slot layout is
// exercised, not only the maths.
texture2D grain;
uniform float amount = 0.6;
uniform float2 offset = float2(0.1, -0.2);
uniform float3 tint = float3(0.9, 0.5, 0.2);
uniform float4 edge = float4(0.2, 0.4, 0.6, 0.8);
float4 main() {
    float g = tex2D(grain, uv * 2.0 + offset).r;
    float e = smoothstep(edge.x, edge.w, uv.x) * edge.y + edge.z * 0.2;
    return float4(tint * (g * amount + e), 1);
}

ember.sl.source:
// A fire, in one file: one texture, one loop, one function.
//
// Everything a Unity shader makes you write that is not the effect is absent.
// No Properties block, no SubShader, no CGPROGRAM, no appdata or v2f, no
// _Time.y. `uniform` declares the slot AND the name React binds against, and
// `texture2D` does the same for a sampler.
//
// This program sits at exactly 8 of the VM's 8 registers, which is the real
// ceiling and not a soft one: adding another live value here is refused when
// the game is built rather than rendered wrong. That is the trade for a
// program that runs interpreted in a browser and compiled after an eject from
// the same file, with no edit in between.
texture2D smoke;

uniform float heat = 0.55;
uniform float2 source = float2(0.5, 0.08);

// Layered noise: one texture, three scales, drifting.
//
// The loop UNROLLS at build time. `i` is a number the parser substitutes, so
// both backends see straight line code and neither needs a branch, which is
// also why the bound has to be a constant. The function inlines, so calling it
// costs exactly what writing the three lines out would.
float plume(float2 p, float t) {
    float s = 0;
    for (int i = 0; i < 3; i++) {
        s = s + tex2D(smoke, p * (1 + i * 1.9) - t).r * (0.6 / (1 + i));
    }
    return s;
}

float4 main() {
    float2 p = uv - source;
    // A cone: narrow across, tall up, brightest at the source.
    float cone = saturate(1 - length(p * float2(3, 1.1)));
    float fuel = saturate(cone * (0.5 + heat) * (plume(p, time * 0.4) + 0.35));

    // Colours as written. They are mixed in sRGB and converted once, so the
    // ramp reads as evenly as its swatches do.
    return ramp(fuel, #00000000, #b53205cc, #ff8a20, #ffe7b0);
}

hex.sl.source:
// An anchor: a hex colour is sRGB as written and the program converts it to
// linear, so a Linear target stores exactly the bytes written here.
float4 main() { return #ff8040; }

orient.sl.source:
// An anchor: red is uv.x, green is uv.y, so a golden's orientation and its
// linear-to-sRGB store can be checked against arithmetic, not against itself.
float4 main() { return float4(uv.x, uv.y, 0, 1); }

ripple.sl.source:
// Every pixel of the surface runs this function, at once, on the GPU.
//
// uv says where this pixel is, 0 to 1 across the surface. time is the clock.
// `uniform` is the wire back to JavaScript: declare one here and its name is
// what the uniforms prop accepts, checked against the .d.ts the build writes
// beside this file.
uniform float spread = 0.4;

float4 main() {
    float d = length(uv - 0.5);
    float wave = sin(d * 44 - time * 3) * 0.5 + 0.5;
    float ring = wave * smoothstep(0.55, 0.0, d) * (spread * 0.9 + 0.1);
    return float4(lerp(float3(0.05, 0.06, 0.09), float3(0.42, 0.78, 1.0), ring), 1);
}

texture.sl.source:
// An anchor: the texture itself, so its orientation and its sRGB decode can be
// checked against the texture's own definition.
texture2D t;
float4 main() { return tex2D(t, uv); }

tuner.sl.source:
// The whole shader, and nothing that is not the shader.
//
// No Properties block, no SubShader, no CGPROGRAM, no appdata or v2f, no
// _Time.y: `uniform` declares both the slot and the name the sliders bind
// against, and the file IS the fragment function.
uniform float warp = 0.5;
uniform float hue = 0.5;
uniform float speed = 0.5;

float4 main() {
    float t = time * (speed * 1.6 + 0.1);
    float2 p = (uv - 0.5) * (warp * 14 + 2);

    float v = sin(p.x + t)
            + sin(p.y - t * 0.8)
            + sin((p.x + p.y) * 0.7 + t * 1.3);

    float n = saturate(v * 0.22 + 0.5);
    float3 rgb = hsv2rgb(float3(frac(hue + n * 0.18), 0.75, n * 0.7 + 0.25));
    return float4(rgb, 1);
}

sdf-circle.sl.source:
float4 main() {
    float2 p = (uv - 0.5) * 1.2;
    float d = sdf.circle(p, 0.35);
    return float4(0.5 + 0.5 * cos(d * 40.0), 0.5 + 0.5 * sin(d * 23.0), saturate(0.5 - d * 2.0), 1);
}

